schemas.schema-01-systematic.prisma:
/// Channel Master - Implements the forum partition and board organization from 'Discussion Board Management'. Provides structural root for categorizing boards into high-level channels like 'Politics', 'Economics', etc. Enforces 3NF by avoiding redundancy in boards/posts and enabling scalable navigation.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_channels {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique channel row identifier.
  id String @id @db.Uuid

  /// Unique channel code for reference in API/config/logic. Example: 'pol', 'econ'. 3NF, unique, enables lookup/automation.
  code String

  /// Channel name for display and navigation. Example: 'Politics'. User-facing, normalized, not derived.
  name String

  /// Expanded channel explanation for users. Optional, supports UI clarity/accessibility. Example: 'Debate and analyze global politics.'
  description String?

  /// Channel order in UI or navigation. Integer sequence for manual arrangement—never calculated.
  position Int @db.Integer

  /// Is channel active/visible? Implements archiving/soft-delete logic from requirements. Not derived, enforced atomic.
  active Boolean

  /// Created timestamp for audit trail and debugging.
  created_at DateTime @db.Timestamptz

  /// Last modification timestamp for history/compliance.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  discussionboard_sections                discussionboard_sections[]
  discussionboard_notifications           discussionboard_notifications[]
  discussionboard_settings                discussionboard_settings[]
  discussionboard_audit_logs_of_actor_id  discussionboard_audit_logs[]    @relation("discussionboard_audit_logs_of_actor_id")
  discussionboard_audit_logs_of_target_id discussionboard_audit_logs[]    @relation("discussionboard_audit_logs_of_target_id")

  @@unique([code])
  @@index([active])
  @@index([position])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Section Master - Implements channel subdivision for structured forum hierarchy (Channel → Section → Board). Reduces clutter; 3NF prevents board/post denormalization. Maps to forum topics (Asia, Policy, Announcements, etc). Enforces single-channel constraint—each section must belong to a channel.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_sections {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique section row identifier.
  id String @id @db.Uuid

  /// Parent channel's {@link discussionboard_channels.id}. Strict foreign key; every section is linked to a channel for navigational consistency and data normalization.
  discussionboard_channel_id String @db.Uuid

  /// Unique section code for API/config reference. Example: 'asia', 'us', 'policy'. Not duplicated in boards/posts; ensures normalization.
  code String

  /// Section name for UI display. Example: 'Asia & Pacific Policy'.
  name String

  /// Section explanation or summary. Supports contextual browsing/accessibility. Nullable, as some sections may lack details.
  description String?

  /// Section UI order. Manual integer for customizable navigation; atomic, not calculated.
  position Int @db.Integer

  /// Is section visible/enabled? Enables archiving/soft-delete workflows in requirements without deletions. Not derived.
  active Boolean

  /// Section creation timestamp for logs and compliance.
  created_at DateTime @db.Timestamptz

  /// Last change timestamp for audit/history.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  section_channel discussionboard_channels @relation(fields: [discussionboard_channel_id], references: [id], onDelete: Cascade)

  discussionboard_boards discussionboard_boards[]

  @@unique([discussionboard_channel_id, code])
  @@index([active])
  @@index([position])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// System Configuration Store - Implements global/system-level settings and toggles for runtime business flexibility. 3NF, one config per row (no lists/blobs). Used for feature flags, thresholds, and system parameters per requirements. No denormalized summaries; config items managed independently.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_configurations {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique configuration identifier.
  id String @id @db.Uuid

  /// Setting key (e.g., 'max_post_per_hour'). Used for lookups and automation. One row per config. 3NF enforced by uniqueness.
  key String

  /// Setting value (always string for flexibility, conversion in app logic). Nullable to support unset/optional configs (e.g., 'true', '5').
  value String?

  /// Human-meaningful description for admin support, UI docs, and compliance. Optional, for clarity/support only.
  description String?

  /// Audit field: when the config was created/added.
  created_at DateTime @db.Timestamptz

  /// Last modification time for change tracking.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([key])
}

/// System Notification Log - Logs every system notification sent for delivery record, debugging, and compliance ('Notifications & Updates', 'Audit & Compliance'). Information is normalized—does not calculate or store aggregate counts. Optionally associates with a user/entity by uuid, never with denormalized info. Does not duplicate status info already elsewhere (only atomic notification row).
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_notifications {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique notification log record.
  id String @id @db.Uuid

  /// Entity/user that received the notification (nullable, as not all notifs are personalized). App-resolved; not enforced by DB-level foreign key.
  target_id String? @db.Uuid

  /// Event type (e.g., 'user_mention', 'system_announcement'). Drives notification flows. Not enum, normalized string, not derived.
  type String

  /// Notification summary title for user display (e.g., 'Your post was reported'). Fulfills clarity/UX requirement.
  title String

  /// Full notification message. Allows null for status-only notifs (e.g., icon/symbol-only in mobile UI).
  body String?

  /// Is notification delivery confirmed? Implements audit flag—not calculated or derived.
  delivered Boolean

  /// Creation log timestamp—required for audit/sync.
  created_at DateTime @db.Timestamptz

  /// If delivered, the actual delivery timestamp. Nullable as delivery may fail/skip.
  delivered_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  notification_target discussionboard_channels? @relation(fields: [target_id], references: [id], onDelete: Cascade)

  @@index([target_id])
  @@index([delivered])
  @@index([type])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Per-Feature/Area Settings Table - Stores specific settings applicable to a context/scope (not global configs). Used for per-channel/section/feature toggles as per 'System Settings' requirements. 3NF, does not duplicate values from configuration. Scoped by id/type (nullable when not tied to a specific entity).
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_settings {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique settings row id.
  id String @id @db.Uuid

  /// Entity or area identifier for which setting applies. Nullable for global context; referential at app-level only.
  scope_id String? @db.Uuid

  /// Scope: identifies type (e.g., 'channel','section','feature_flag'). For app/UI routing. Normalized string.
  scope_type String

  /// Setting key identifying the individual toggle/option. E.g., 'moderation_policy'. Not redundant vs. global config.
  key String

  /// Setting value (flag, string, limit, etc). Nullable for unset/optional options.
  value String?

  /// Admin-facing notes/explanations. For docs/audit clarity.
  description String?

  /// Created time (audit and config tracing).
  created_at DateTime @db.Timestamptz

  /// Modification time (audit and compliance).
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  settings_scope discussionboard_channels? @relation(fields: [scope_id], references: [id], onDelete: Cascade)

  @@unique([scope_type, scope_id, key])
  @@index([scope_id])
  @@index([key(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// System Audit Log - Records all critical, privileged, moderation, admin, or config actions. Fulfills trace and compliance requirements for role escalation, post deletion, and sensitive changes (see 'Audit & Compliance'). Each log links to the user/id that performed the action and optionally the entity affected. 3NF with atomized actions only; no aggregates, counts, or derived data.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_audit_logs {
  //----
  // COLUMNS
  //----
  /// Primary Key. Each row is an atomic action/event.
  id String @id @db.Uuid

  /// Id of member/admin/moderator who performed action. Required so audit is always attributable. Enforced by application logic (typically links to users in the Actors component).
  actor_id String @db.Uuid

  /// Id of entity/post/board/etc. affected by the action. Nullable for system/global/infrastructure events.
  target_id String? @db.Uuid

  /// Type/classification of audit event (e.g., 'post_deleted','role_assigned','settings_changed'). For reporting and compliance. Atomic, normalized string.
  action String

  /// JSON string/serialized details of event context; e.g., diff, reason, metadata. Nullable for simple events. Not calculated, added by app at the time.
  payload String?

  /// When the action/event occurred (timestamp, always present for audit).
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  audit_actor  discussionboard_channels  @relation("discussionboard_audit_logs_of_actor_id", fields: [actor_id], references: [id], onDelete: Cascade)
  audit_target discussionboard_channels? @relation("discussionboard_audit_logs_of_target_id", fields: [target_id], references: [id], onDelete: Cascade)

  @@index([target_id])
  @@index([actor_id])
  @@index([action])
}

schemas.schema-02-actors.prisma:
/// Actor entity — Implements the 'User Onboarding & Authentication', 'Posting & Interaction', and 'Roles & Permissions Matrix' requirements. Represents a unique human member of the discussion board system, providing the foundation of the actor domain. Fully normalized (3NF), containing only atomic information directly tied to the member and delegating profile/preferences to separate models. Example usages: authenticating users, referencing post authors, assigning roles. Key relationships: referenced by posts, comments, and role tables. Special rules: Unique per user; deleted_at supports soft deletion and audit.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_members {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique user identifier for this member.
  id String @id @db.Uuid

  /// Member's unique username for login and display. Implements 'User Onboarding & Authentication' requirements; ensures normalization by preventing direct duplication in profile or role tables. Required, non-nullable. Example: 'civicUser42'.
  username String

  /// Member's unique, verified email address for authentication and notifications. Implements 'User Onboarding & Authentication' and privacy requirements. Normalization: maintained by separating from profile fields. Example: 'user@email.com'.
  email String

  /// Securely stored password hash for authentication (NEVER actual plaintext password). Implements security aspects of 'User Onboarding & Authentication'. Always normalized and never duplicated elsewhere. Required for login; example: 'bcrypt$...'.
  hashed_password String

  /// Current assigned role. Implements 'Roles & Permissions Matrix', designating user's system privilege. Normalization: Single authoritative field. Example: 'member', 'moderator', 'admin'.
  role String

  /// Indicates if the member account is currently active. Used to temporarily disable users (e.g., for bans, unverified accounts). Normalized flag; never pre-computed. Example: true/false.
  is_active Boolean

  /// Timestamp when the member joined the system. Audit and analytics support. Not calculated; single source of truth. Example: '2024-07-24T11:01:24.974+09:00'.
  created_at DateTime @db.Timestamptz

  /// Timestamp of last member data update. Used for audit, profile management, and activity tracking. Always normalized, never derived. Example: '2024-07-25T14:30:00+09:00'.
  updated_at DateTime @db.Timestamptz

  /// Timestamp for soft deletion of member account, or null if the account is active. Supports audit trail and data erasure. Ensures normalization and compliance with privacy regulations. Example: null or '2024-08-01T09:00:00+09:00'.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  discussionboard_moderators               discussionboard_moderators?
  discussionboard_admins                   discussionboard_admins?
  discussionboard_member_profiles          discussionboard_member_profiles?
  discussionboard_member_preferences       discussionboard_member_preferences?
  discussionboard_threads                  discussionboard_threads[]
  discussionboard_thread_snapshots         discussionboard_thread_snapshots[]
  discussionboard_posts                    discussionboard_posts[]
  discussionboard_post_snapshots           discussionboard_post_snapshots[]
  discussionboard_post_votes               discussionboard_post_votes[]
  discussionboard_post_reports             discussionboard_post_reports[]
  discussionboard_comments                 discussionboard_comments[]
  discussionboard_comment_snapshots        discussionboard_comment_snapshots[]
  discussionboard_comment_votes            discussionboard_comment_votes[]
  discussionboard_comment_reports          discussionboard_comment_reports[]
  discussionboard_reports                  discussionboard_reports[]
  discussionboard_bans                     discussionboard_bans[]
  discussionboard_warnings                 discussionboard_warnings[]
  discussionboard_engagement_metrics       discussionboard_engagement_metrics[]
  discussionboard_activity_logs            discussionboard_activity_logs[]
  discussionboard_notification_preferences discussionboard_notification_preferences[]
  discussionboard_data_erasure_requests    discussionboard_data_erasure_requests[]

  @@unique([username])
  @@unique([email])
  @@index([created_at])
}

/// Moderator role assignment — Implements 'Moderator Journey', 'Roles & Permissions Matrix', and 'Moderation & Reporting' requirements. This table grants moderator privileges to selected members, tracking assignment duration and status. Fully normalized: stores only data directly related to the moderator assignment, not member details. Example: assigning John (discussionboard_member_id) as a moderator from 2024-07-24 to 2024-09-01. Key relationship: FK to discussionboard_members. Special: Enforces 1:1 mapping per member, audited by start/end timestamps.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_moderators {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for the moderator assignment.
  id String @id @db.Uuid

  /// Target member's {@link discussionboard_members.id}. Identifies which user is granted moderator privileges.
  member_id String @db.Uuid

  /// Admin's {@link discussionboard_admins.id} who assigned the moderator role. For audit and compliance; always references existing admin.
  assigned_by_admin_id String @db.Uuid

  /// Timestamp when moderator rights were granted. Implements moderation workflow requirements and audit. Normalized field, set at assignment. Example: '2024-07-24T11:15:00+09:00'.
  assigned_at DateTime @db.Timestamptz

  /// When moderator assignment expires, if temporary; null for permanent. Implements 'Temporary Permissions' business process. Ensures normalization: no derived status. Example: null or cutoff time.
  expires_at DateTime? @db.Timestamptz

  /// Timestamp moderator rights are revoked, or null if active. Track the duration and revocation events for compliance.
  revoked_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_moderator_member discussionboard_members @relation(fields: [member_id], references: [id], onDelete: Cascade)

  discussionboard_board_moderators   discussionboard_board_moderators[]
  discussionboard_moderation_actions discussionboard_moderation_actions[]
  discussionboard_bans               discussionboard_bans[]
  discussionboard_warnings           discussionboard_warnings[]

  @@unique([member_id])
  @@index([assigned_at])
}

/// Administrator role assignment — Implements 'Admin Journey', 'Roles & Permissions Matrix', and 'Role Escalation' business rules. Represents users granted full administrative privileges. Contains assignment and status audit details only, normalized away from member records. Usage: assigning/removing admins, enforcing escalations, logging system changes. Key: FK to member, 1:1 mapping. Special: References assignment metadata for security/traceability.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_admins {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for the admin assignment.
  id String @id @db.Uuid

  /// Target member's {@link discussionboard_members.id} with admin access. Direct 1:1 mapping to unique member.
  member_id String @db.Uuid

  /// Admin's {@link discussionboard_admins.id} who performed the admin role assignment. Supports traceable, auditable escalation control. Always references another admin (may reference self if bootstrap).
  assigned_by_admin_id String @db.Uuid

  /// Timestamp when admin rights were granted. Key for audit trail & compliance with 'Audit Trail' requirements. Example: '2024-07-24T11:20:00+09:00'.
  assigned_at DateTime @db.Timestamptz

  /// Timestamp of admin privilege revocation, or null if active. Ensures clear audit of all admin escalation events. Example: null or revocation time.
  revoked_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_admin_member discussionboard_members @relation(fields: [member_id], references: [id], onDelete: Cascade)

  @@unique([member_id])
  @@index([assigned_at])
}

/// Member profile — Implements 'Profile Setup', 'User Journey', and privacy requirement sections. Contains extended, user-editable profile details (not security/role related), normalized from core member table. Supports flexible addition of non-auth data (display_name, bio, links). Full normalization ensures all profile attributes relate solely to the member's public-facing info, not account details. Example: viewing public member card. FK to member; 1:1. Constraints: Each member has at most one profile record.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_member_profiles {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies each profile.
  id String @id @db.Uuid

  /// Associated member's {@link discussionboard_members.id}. 1:1 mapping, unique.
  member_id String @db.Uuid

  /// User-chosen display name. Implements profile setup requirements and user personalization. Example: 'Jane Economist'. Normalized as only present in profile table.
  display_name String

  /// Short member biography/summary. Business: used in member card displays. Optional for privacy. Example: 'Policy researcher and economic writer.'
  bio String?

  /// Profile picture/avatar URI. Sets user identity visually; optional per requirements for privacy/flexibility. Example: 'https://site.com/avatar/abc.png'.
  avatar_url String? @db.VarChar(80000)

  /// Free text user location (city, country). Implements user journey customizations and regional sorting. Example: 'Seoul, Korea'.
  location String?

  /// User's website link. Supports networking; optional for privacy and safety. Example: 'https://myportfolio.com'.
  website_url String? @db.VarChar(80000)

  //----
  // RELATIONS
  //----
  fk_profile_member discussionboard_members @relation(fields: [member_id], references: [id], onDelete: Cascade)

  @@unique([member_id])
  @@index([display_name])
}

/// Member notification and settings preferences — Implements 'Notifications & Updates', 'Accessibility & Usability', and 'User Journey' requirements. Records user-controlled preferences for notifications, UI configuration, and possibly localization settings. Maintains normalization: stores only true user settings, never derived data or cached computations. Example: preference for email notifications true, weekly digests suppressed. FK to member; 1:1 record. Special: nulls permitted for unset defaults.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_member_preferences {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for this set of preferences.
  id String @id @db.Uuid

  /// Preferences' owner {@link discussionboard_members.id}. Enforces 1:1 mapping.
  member_id String @db.Uuid

  /// Whether the member opts to receive email notifications. Implements 'Notifications & Updates'. Normalized to avoid caching state elsewhere. Example: true/false.
  receive_email_notifications Boolean?

  /// Whether the member allows push notifications. Business: compliance with member preferences for engagement. Normalized, never derived. Example: true/false.
  receive_push_notifications Boolean?

  /// Member's preferred language code (e.g., 'en', 'ko'). Supports 'Accessibility & Usability' and localization requirements. Normalization: only presence, not cached translations. Example: 'en'.
  preferred_language String?

  /// Member preference for dark mode UI. Implements accessibility requirements. Normalized (single source for UI theme settings). Example: true/false.
  dark_mode_enabled Boolean?

  //----
  // RELATIONS
  //----
  fk_preferences_member discussionboard_members @relation(fields: [member_id], references: [id], onDelete: Cascade)

  @@unique([member_id])
}

schemas.schema-03-boards.prisma:
/// Board entity - This implements the board management and categorization requirement from the requirements analysis (Business Requirements #2, User Journey #3).
///
/// A board represents a single discussion space, usually per broad topic (e.g., Global Economics, Politics). Organizes threads and posts under user-driven topics. Maintains 3NF compliance by ensuring all meta/setting data is separated—actual posts or threads are stored in separate tables/files.
///
/// For example, a single 'Political News' board contains many threads, all linked via threads table. Key relationships: links to category, board_settings, section (external); may be moderated by multiple moderators via discussionboard_board_moderators. Special behaviors: Boards may be visible, archived, or require moderation.
///
/// @namespace Boards
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_boards {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique board identifier.
  id String @id @db.Uuid

  /// Category for this board's {@link discussionboard_board_categories.id}. Groups boards under categories such as 'Economics' or 'Politics.'
  discussionboard_board_category_id String @db.Uuid

  /// Section reference for this board's {@link discussionboard_sections.id}. Sections are higher-level partitions managed in 'Systematic', supporting navigation and access control.
  discussionboard_section_id String @db.Uuid

  /// Board name - Implements name labeling from requirements. Human-readable board label (e.g., 'US Macro Policy') visible in navigation. Normalization: Name only, localized names managed separately for i18n.
  name String

  /// Board code - Unique code for programmatic lookup (e.g., 'pol_news'). Used in URLs/routing. Ensures normalization by decoupling identifier from visible name.
  code String

  /// Short board description - Implements descriptive labeling per User Journey & Usability. Used for tooltips or previews in UI. Ensures normalization by making this field atomic. Example: 'Current events and news in global politics.'
  description String?

  /// Whether this board is currently active and can accept new threads/posts. Implements platform-wide board lifecycle from business rules. E.g., set false if archived. Normalizes state transitions via single Boolean atomic value.
  is_active Boolean

  /// Whether this board is visible to members. If false, board is hidden from public lists (e.g., for private or staff-only spaces). Supports advanced access control workflows. Normalized as single Boolean flag.
  is_visible Boolean

  /// Timestamp of board creation. Implements requirement for content and board lifecycle audit.
  created_at DateTime @db.Timestamptz

  /// Last modification time for the board. Implements requirement for audit trails; enables UI to show freshness.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_discussionboard_boards_category discussionboard_board_categories @relation(fields: [discussionboard_board_category_id], references: [id], onDelete: Cascade)
  fk_discussionboard_boards_section  discussionboard_sections         @relation(fields: [discussionboard_section_id], references: [id], onDelete: Cascade)

  discussionboard_board_settings     discussionboard_board_settings?
  discussionboard_board_moderators   discussionboard_board_moderators[]
  discussionboard_threads            discussionboard_threads[]
  discussionboard_posts              discussionboard_posts[]
  discussionboard_engagement_metrics discussionboard_engagement_metrics[]
  discussionboard_activity_logs      discussionboard_activity_logs[]
  discussionboard_trending_topics    discussionboard_trending_topics[]

  @@unique([code])
  @@index([discussionboard_board_category_id])
  @@index([discussionboard_section_id])
  @@index([created_at])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Board Category entity - Implements the organizational category requirement for grouping boards into top-level classes (Business Requirements #2, Usability).
///
/// A category represents a container for related boards (e.g., 'Economics', 'Politics'). Maintains strict 3NF: category only links meta-data; boards linked via FK. For example, a user browsing by category sees all boards for that subject. Key relationships: referenced by boards; never contains board details directly. Special behaviors: Categories may be edited by admins only.
///
/// @namespace Boards
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_board_categories {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique category identifier.
  id String @id @db.Uuid

  /// Category name. Implements category labeling from requirements. Used in UI menus and filters. Ensures normalization by keeping names atomic. Example: 'Global Economics'.
  name String

  /// Short unique code for category (e.g., 'econ'). Used for programmatic referencing. Ensures normalization by separating technical from display names.
  code String

  /// Short description of category. Used as tooltips or previews in UI. Normalizes business logic by isolating display info from operational relationships. Example: 'Boards devoted to global and national economic issues.'
  description String?

  /// Ordering hint for category. Determines sort order in UI. Normalizes ordering logic as atomic per-category value; actual order set by admin. Example: 1 for top, 2 for second-level.
  position Int @db.Integer

  /// Creation timestamp. Used for audits and ordering.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  discussionboard_boards discussionboard_boards[]

  @@unique([code])
  @@unique([name])
  @@index([position])
  @@index([created_at])
}

/// Board Settings entity - Implements per-board configuration from business requirements (esp. Admin Journey #3, Board Configurations).
///
/// Each record contains settings (not content) for a specific board: various advanced flags and limits central to system operation. Maintains 3NF by completely separating board meta/config from threads/posts. For example, allows a board to require invite-only posting, limit max posts per hour, or toggle advanced features without affecting normal thread data. Key relationships: linked one-to-one to a board; referenced only via FK, not duplicated. Special behaviors: Any schema-altering or configuration parameter not fitting as content goes here. Only editable by admins.
///
/// @namespace Boards
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_board_settings {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique setting record identifier.
  id String @id @db.Uuid

  /// Board reference for this settings row's {@link discussionboard_boards.id}. Each board has exactly one associated settings record; enforced via unique index (1:1).
  discussionboard_board_id String @db.Uuid

  /// Whether the board is currently read-only (locked down for maintenance/moderation). Implements business rules for moderation/admin locking. 3NF: Atomic flag per board only.
  is_locked Boolean

  /// Whether new thread/posts require moderator/admin approval. Implements business requirements for strict moderation boards. Example: True for high-risk debate boards. 3NF: Atomic per-board policy.
  require_approval_for_posting Boolean

  /// Rate limiting configuration: maximum allowed new posts per user per hour. Implements platform anti-spam rules from business rules/workflows (#2). 3NF: One per board; enforced in services, not duplicated elsewhere.
  max_posts_per_hour Int @db.Integer

  /// Board can be browsed by non-members (logged-out users) if true. Implements accessibility/visibility requirements. 3NF: Atomic viewability policy per board.
  allow_anonymous_viewing Boolean

  /// Allows users to attach/upload files in this board. Implements extended board rule configuration. 3NF: Atomic setting.
  allow_file_uploads Boolean

  /// Creation timestamp for audit trail and recovery policies.
  created_at DateTime @db.Timestamptz

  /// Last settings update date. Used for support/forensics/audit trail in compliance needs.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_discussionboard_board_settings_board discussionboard_boards @relation(fields: [discussionboard_board_id], references: [id], onDelete: Cascade)

  @@unique([discussionboard_board_id])
  @@index([created_at])
}

/// Board Moderator Membership entity - Implements the many-to-many linkage between boards and moderators (Business Rules, Escalation, Roles #3).
///
/// Represents the assignment of one or more moderators (from 'discussionboard_moderators', already in Actors) to one or more boards. Maintains 3NF by offloading the relationship to this junction, not duplicating moderator/board data. For example, a moderator can oversee several boards, and each board can have several moderators. Key relationships: FKs to boards and moderators; enabling moderator reassignment or board cleanup without duplication. Special behaviors: May include an 'is_primary' flag for head moderator and a 'joined_at' timestamp for auditing assignments.
///
/// @namespace Boards
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_board_moderators {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique record representing single board-moderator link.
  id String @id @db.Uuid

  /// Board reference for this assignment's {@link discussionboard_boards.id}.
  discussionboard_board_id String @db.Uuid

  /// Moderator reference for this link's {@link discussionboard_moderators.id}.
  discussionboard_moderator_id String @db.Uuid

  /// Is this moderator currently primary for the board? Implements workflow for escalations (see Escalation section in requirements). Allows UI to highlight responsible moderator. 3NF: Atomic per-link value, not in main board record.
  is_primary Boolean

  /// When was this moderator assigned to this board? Implements audit/compliance and appeals workflows. Normalized as timestamp field for ordering assignments and reversals.
  joined_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_discussionboard_board_moderators_board     discussionboard_boards     @relation(fields: [discussionboard_board_id], references: [id], onDelete: Cascade)
  fk_discussionboard_board_moderators_moderator discussionboard_moderators @relation(fields: [discussionboard_moderator_id], references: [id], onDelete: Cascade)

  @@unique([discussionboard_board_id, discussionboard_moderator_id])
  @@index([discussionboard_board_id])
  @@index([discussionboard_moderator_id])
  @@index([joined_at])
}

schemas.schema-04-threads.prisma:
/// Discussion Thread - This implements the core thread entity from business requirements: providing a root container for posts, tags, and timeline organization (ref: 01_business_requirements_discussionboard.md, 02_user_journey_and_use_cases_discussionboard.md). Threads are created by members in specific boards and serve as the main aggregation unit for posts/comments. Strict 3NF compliance: no denormalized or calculated fields, all relationships explicit. Example usage: thread on 'Inflation in 2025' in board 'Macroeconomics'. Key relationships: links to boards and thread authors (members).
///
/// @namespace Threads
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_threads {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for the thread, ensuring referential integrity.
  id String @id @db.Uuid

  /// Board reference — Points to {@link discussionboard_boards.id} (foreign key). Implements thread-to-board organization.
  board_id String @db.Uuid

  /// Thread author reference — Points to {@link discussionboard_members.id} (foreign key). Fulfills thread authorship and audit trails.
  author_member_id String @db.Uuid

  /// Thread title — Implements discoverability, search, and sorting requirements. Atomic subject line. Example: 'Monetary Policy Trends'.
  title String

  /// Thread description or leading body content. May be null for threads with only posts. Example: 'Discussion about latest trends...'.
  body String?

  /// Creation timestamp. Implements timeline, ordering, audit, and moderation controls. Example: '2025-07-24T19:01:24Z'.
  created_at DateTime @db.Timestamptz

  /// Last updated timestamp. Changes with edit; informs sorting, audit, and moderation workflow.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp (nullable). Used for retention, restore, and moderation/audit workflows. Null if not deleted, else set to deletion time.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_discussionboard_threads_board         discussionboard_boards  @relation(fields: [board_id], references: [id], onDelete: Cascade)
  fk_discussionboard_threads_author_member discussionboard_members @relation(fields: [author_member_id], references: [id], onDelete: Cascade)

  discussionboard_thread_snapshots discussionboard_thread_snapshots[]
  discussionboard_thread_tags      discussionboard_thread_tags[]
  discussionboard_posts            discussionboard_posts[]
  discussionboard_post_references  discussionboard_post_references[]
  discussionboard_activity_logs    discussionboard_activity_logs[]
  discussionboard_trending_topics  discussionboard_trending_topics[]

  @@unique([board_id, title])
  @@index([author_member_id])
  @@index([created_at])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Thread Snapshot - Implements versioning/audit trail for full edit and moderation history (see: 04_business_rules_and_workflows_discussionboard.md). 3NF compliance. Each snapshot is a version of the thread’s title/body at a point in time. Example: if a thread is edited, a new snapshot is stored with reason and actor data. Relationships: back-references discussionboard_threads, references editing actor (member/moderator/admin). Snapshots are immutable, supporting rollback and thorough audit.
///
/// @namespace Threads
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_thread_snapshots {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each snapshot instance.
  id String @id @db.Uuid

  /// Thread reference. Points to {@link discussionboard_threads.id} to record which thread this snapshot belongs to.
  thread_id String @db.Uuid

  /// Actor reference for who made this snapshot. Points to {@link discussionboard_members.id}; null if system-generated.
  actor_id String? @db.Uuid

  /// Title at this snapshot version. Atomic snapshot of the title for audit/history. Example: 'Initial Title'.
  title String

  /// Body/content at this version. Enables full rollback/restoration. Example: 'First version with full description.'
  body String?

  /// Edit/mutation reason: moderator note or inline user edit note. Fulfills audit/compliance needs.
  reason String?

  /// Creation timestamp of snapshot version for precise audit history.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_discussionboard_thread_snapshots_thread discussionboard_threads  @relation(fields: [thread_id], references: [id], onDelete: Cascade)
  fk_discussionboard_thread_snapshots_actor  discussionboard_members? @relation(fields: [actor_id], references: [id], onDelete: Cascade)

  @@index([actor_id])
  @@index([thread_id, created_at])
}

/// Thread Tag Assignment - Provides M:N relationship between threads and tags for discoverability and content organization (see: content organization requirements). This is a strict 3NF bridge table. Tracks assignment/removal. Each record links a tag to a thread, with assignment/removal timestamps. Example: Marking a thread with 'fiscal-policy'. Key relationships: threads and tags (discussionboard_tags). 
///
/// @namespace Threads
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_thread_tags {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique for each tagging event.
  id String @id @db.Uuid

  /// Thread reference. Points to {@link discussionboard_threads.id} for M:N tagging.
  thread_id String @db.Uuid

  /// Assignment timestamp, marking when tag applied. Aids in timeline and audit support.
  assigned_at DateTime @db.Timestamptz

  /// Removal timestamp, allows for full tag history (null if active, otherwise set). Used for audit, moderation, and restoration.
  removed_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_discussionboard_thread_tags_thread discussionboard_threads @relation(fields: [thread_id], references: [id], onDelete: Cascade)

  @@index([thread_id])
}

schemas.schema-05-posts.prisma:
/// Discussion Board Post — Implements the business requirement for user-generated discussion content and post lifecycle management. Each record represents a single post created by a discussion member under a thread and a board. This maintains 3NF by keeping atomic post attributes and referencing all relationships via foreign keys. Member, thread, board connections ensure correct context. For example, a post with title 'Inflation Impact' by a member in a politics thread.
///
/// @namespace Posts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_posts {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Associated thread's {@link discussionboard_threads.id}. Represents the thread that this post belongs to for content grouping and navigation.
  discussionboard_thread_id String @db.Uuid

  /// Author member's {@link discussionboard_members.id}. Represents who created the post, for authorship, accountability, and permission enforcement.
  discussionboard_member_id String @db.Uuid

  /// Target board's {@link discussionboard_boards.id}. Indicates the board/category where this post appears, enforcing board-topic structure.
  discussionboard_board_id String @db.Uuid

  /// Post title, used to identify the topic at a glance. Fulfills requirement for clarity and discoverability. For example: 'Global Trade Policy Updates'.
  title String

  /// Main post content. Full textual body provided by member. Ensures full normalization, no aggregation. Example: argument, opinion, or news analysis.
  body String

  /// Soft-deletion flag; true if logically deleted but present for audit. Part of lifecycle/audit rule compliance. Not a hard deletion field.
  is_deleted Boolean

  /// Record creation timestamp for post, to provide audit trails and ordering.
  created_at DateTime @db.Timestamptz

  /// Timestamp of the post's latest update, required for version tracking and auditability.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  thread discussionboard_threads @relation(fields: [discussionboard_thread_id], references: [id], onDelete: Cascade)
  member discussionboard_members @relation(fields: [discussionboard_member_id], references: [id], onDelete: Cascade)
  board  discussionboard_boards  @relation(fields: [discussionboard_board_id], references: [id], onDelete: Cascade)

  discussionboard_post_snapshots                    discussionboard_post_snapshots[]
  discussionboard_post_votes                        discussionboard_post_votes[]
  discussionboard_post_reports                      discussionboard_post_reports[]
  discussionboard_post_references_of_source_post_id discussionboard_post_references[]   @relation("discussionboard_post_references_of_source_post_id")
  discussionboard_post_references_of_target_post_id discussionboard_post_references[]   @relation("discussionboard_post_references_of_target_post_id")
  discussionboard_comments                          discussionboard_comments[]
  discussionboard_comment_snapshots                 discussionboard_comment_snapshots[]
  discussionboard_activity_logs                     discussionboard_activity_logs[]

  @@unique([discussionboard_thread_id, title])
  @@index([discussionboard_member_id])
  @@index([discussionboard_board_id])
  @@index([created_at])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Post Content Snapshot — Implements the requirement for post version history and audit/compliance. Each snapshot stores the full state of a post at a time (title, body, editor), maintaining 3NF. Enables rollback, review, and transparency. Links to affected post and member who made edit, supporting moderation and appeals.
///
/// @namespace Posts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_post_snapshots {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Parent post's {@link discussionboard_posts.id}, enabling reconstruction of edit/version history.
  discussionboard_post_id String @db.Uuid

  /// Editor member's {@link discussionboard_members.id}. Null if system or deleted member. Supports full audit and rollback.
  editor_member_id String? @db.Uuid

  /// Snapshot of the post's title at the time of change; supports accurate versioning. Example: 'Initial Title'.
  title String

  /// Snapshot of full post body at edit time, necessary for rollback and transparency.
  body String

  /// Timestamp when the snapshot was recorded. Key for reconstructing version timeline.
  taken_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  post          discussionboard_posts    @relation(fields: [discussionboard_post_id], references: [id], onDelete: Cascade)
  editor_member discussionboard_members? @relation(fields: [editor_member_id], references: [id], onDelete: Cascade)

  @@index([discussionboard_post_id])
  @@index([editor_member_id])
  @@index([taken_at])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Post Vote — Supports upvote/downvote/business ranking features. 3NF compliance: only atomic per-member per-post records, not tallies. Each record is a single member's vote on a single post. Unique constraint prevents duplicate votes. Example: member upvoting a post.
///
/// @namespace Posts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_post_votes {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Voted post's {@link discussionboard_posts.id}.
  discussionboard_post_id String @db.Uuid

  /// Voter's {@link discussionboard_members.id}. Member who cast the vote.
  discussionboard_member_id String @db.Uuid

  /// The vote value: 1 for upvote, -1 for downvote, 0 for neutral/removed. Completely normalized, not aggregate.
  vote_type Int @db.Integer

  /// When the vote was cast. Necessary for analytics and audit/compliance.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  post   discussionboard_posts   @relation(fields: [discussionboard_post_id], references: [id], onDelete: Cascade)
  member discussionboard_members @relation(fields: [discussionboard_member_id], references: [id], onDelete: Cascade)

  @@unique([discussionboard_post_id, discussionboard_member_id])
  @@index([discussionboard_member_id])
  @@index([created_at])
}

/// Post Report — Tracks reporting and moderation for compliance requirements. Each record represents a single moderation report against a post, including what, who, and why. Maintains strict normalization: each report is atomic, never aggregate. For example, one member reports a post for abuse, specifying type and optional text. Linked to moderation actions via type id.
///
/// @namespace Posts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_post_reports {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Reported post's {@link discussionboard_posts.id}.
  discussionboard_post_id String @db.Uuid

  /// Reporting member's {@link discussionboard_members.id}.
  reporter_member_id String @db.Uuid

  /// Type of report {@link discussionboard_report_types.id}.
  report_type_id String @db.Uuid

  /// Freeform text supplied by reporter for context. Nullable. Example: 'Offensive language.'
  description String?

  /// When the report was submitted; required for audit and compliance.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  post            discussionboard_posts        @relation(fields: [discussionboard_post_id], references: [id], onDelete: Cascade)
  reporter_member discussionboard_members      @relation(fields: [reporter_member_id], references: [id], onDelete: Cascade)
  report_type     discussionboard_report_types @relation(fields: [report_type_id], references: [id], onDelete: Cascade)

  @@index([discussionboard_post_id])
  @@index([reporter_member_id])
  @@index([report_type_id])
  @@index([created_at])
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Post Reference — Implements the requirement for referencing/post linking (content cross-linking, citation, or mention). Keeps each reference atomic (single from-one-to-another relationship); enforces normalization rigorously. Supports reference to posts or threads (polymorphic). Example: A post referencing another post for citation.
///
/// @namespace Posts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_post_references {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// This (source) post's {@link discussionboard_posts.id}.
  source_post_id String @db.Uuid

  /// Referenced post's {@link discussionboard_posts.id}, can be null for thread/class reference.
  target_post_id String? @db.Uuid

  /// Referenced thread's {@link discussionboard_threads.id}, can be null for post-only reference.
  target_thread_id String? @db.Uuid

  /// Reference type: 'post', 'thread', or 'comment'. String marker for polymorphic reference; not denormalized. Example: 'post'.
  reference_type String

  //----
  // RELATIONS
  //----
  source_post   discussionboard_posts    @relation("discussionboard_post_references_of_source_post_id", fields: [source_post_id], references: [id], onDelete: Cascade)
  target_post   discussionboard_posts?   @relation("discussionboard_post_references_of_target_post_id", fields: [target_post_id], references: [id], onDelete: Cascade)
  target_thread discussionboard_threads? @relation(fields: [target_thread_id], references: [id], onDelete: Cascade)

  @@index([source_post_id])
  @@index([target_post_id])
  @@index([target_thread_id])
  @@index([reference_type])
}

schemas.schema-06-comments.prisma:
/// Top-level entity for Comments domain—this implements the requirements for associating structured, version-controlled user comments with threads and posts from the discussion board, as described in the business rules (see requirements: Posting & Interaction, Moderation, Audit). Purpose: To persist individual member-authored comments under posts, enable thread-based discussions, and facilitate moderation. Strict 3NF normalization is maintained—no derived/calculated fields. Example: User Alice replies to a discussionboard_post, creating a new comment entity. Key relationships: links to parent post, authoring member, version history. Special behaviors: Deletion and editing cascade to comment snapshots and votes.
///
/// @namespace Comments
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_comments {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies each comment record in the table.
  id String @id @db.Uuid

  /// Parent post's {@link discussionboard_posts.id}—connects each comment to its containing post, enabling post-based discussion threading.
  discussionboard_post_id String @db.Uuid

  /// Authoring member's {@link discussionboard_members.id}—identifies who wrote this comment, enforcing accountability and permission checking.
  discussionboard_member_id String @db.Uuid

  /// Optional self-reference to discussionboard_comments.id for nested (reply) comments, allowing recursive threaded discussions. Null for top-level comments.
  parent_id String? @db.Uuid

  /// Main content of the comment. Implements the core posting requirement (3). Ensures normalization by storing only user-authored text per record. For example, the comment: "I disagree with your point because...". No formatting or summary—pure content only.
  body String

  /// Timestamp when the comment was created. Implements audit & compliance requirements for tracking comment lifecycle. Example: '2025-07-24T19:01:24.976Z'.
  created_at DateTime @db.Timestamptz

  /// Timestamp of the latest update (edit). Used for version control/auditing. Enables displaying 'edited' markers. Null if never edited.
  updated_at DateTime? @db.Timestamptz

  /// Soft-deletion marker for comment removal. Null if active. Implements moderation and user workflow for reversible deletion/auditing. Maintains normalization by separating status from content/body.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_discussionboard_comments_post   discussionboard_posts     @relation(fields: [discussionboard_post_id], references: [id], onDelete: Cascade)
  fk_discussionboard_comments_member discussionboard_members   @relation(fields: [discussionboard_member_id], references: [id], onDelete: Cascade)
  fk_discussionboard_comments_parent discussionboard_comments? @relation("recursive", fields: [parent_id], references: [id], onDelete: Cascade)

  recursive                         discussionboard_comments[]          @relation("recursive")
  discussionboard_comment_snapshots discussionboard_comment_snapshots[]
  discussionboard_comment_votes     discussionboard_comment_votes[]
  discussionboard_comment_reports   discussionboard_comment_reports[]
  discussionboard_activity_logs     discussionboard_activity_logs[]

  @@unique([discussionboard_post_id, id])
  @@index([parent_id])
  @@index([discussionboard_member_id])
  @@index([created_at])
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Snapshot/audit history for comments—implements audit trail and historical versioning for moderation and rollback. Implements requirements: Content Quality Assurance, Moderation Escalation, and audit logs. Purpose: To persist every historical version of a comment whenever it's edited or deleted. Maintains full 3NF normalization by storing immutable versions (no calculated fields). Example: When a comment is edited, a new snapshot is created with prior content/metadata. Key relationships: Links to comment, versioned author, and source post. Special behaviors: Readonly after creation; never updated.
///
/// @namespace Comments
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_comment_snapshots {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies each comment snapshot.
  id String @id @db.Uuid

  /// Parent comment's {@link discussionboard_comments.id}—links each snapshot to the main comment being versioned, facilitating audit trails and historical review.
  discussionboard_comment_id String @db.Uuid

  /// The authoring member at the time of this comment version. Implements precise version-era authorship for audit/recovery.
  discussionboard_member_id String @db.Uuid

  /// The parent post's {@link discussionboard_posts.id} at the time of this comment version. Ensures contextual placement of the snapshot even if post-comment relationships evolve.
  discussionboard_post_id String @db.Uuid

  /// Immutable snapshot of the comment's content at the time of this version. Implements forensic review requirements for moderator/admin oversight. For example, an edited comment retains its original wording here.
  body String

  /// Monotonic version number assigned to each comment snapshot for the same comment. Implements requirements for traceable edit history and rollback granularity. For example, version 2 = first edit.
  version Int @db.Integer

  /// Timestamp when the snapshot was created (distinct from the comment's main created_at). Supports ordered audit/review.
  snapshot_created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_discussionboard_comment_snapshots_comment discussionboard_comments @relation(fields: [discussionboard_comment_id], references: [id], onDelete: Cascade)
  fk_discussionboard_comment_snapshots_member  discussionboard_members  @relation(fields: [discussionboard_member_id], references: [id], onDelete: Cascade)
  fk_discussionboard_comment_snapshots_post    discussionboard_posts    @relation(fields: [discussionboard_post_id], references: [id], onDelete: Cascade)

  @@unique([discussionboard_comment_id, version])
  @@index([discussionboard_post_id])
  @@index([discussionboard_comment_id])
  @@index([discussionboard_member_id])
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Normalized mapping of user upvotes/downvotes on comments—implements Posting & Interaction and Moderation requirements for voting (requirements: 3, 4, 8). Purpose: To enable per-member, per-comment recording of up/down votes without duplication or pre-calculation (fully normalized). Example: When member Alice upvotes a comment, a new row links her to that comment, with the vote direction/score. Special behaviors: Uniqueness constraint prevents duplicate votes; allows updates for toggling/removing votes; no aggregate score is stored here—it must be computed via query or via materialized view.
///
/// @namespace Comments
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_comment_votes {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies each comment vote entry.
  id String @id @db.Uuid

  /// Target comment's {@link discussionboard_comments.id}—the comment being voted on.
  discussionboard_comment_id String @db.Uuid

  /// Voting member's {@link discussionboard_members.id}—who cast this vote.
  discussionboard_member_id String @db.Uuid

  /// Stores vote direction for the comment—typically 'up' or 'down' (could use enum at application layer). Implements posting/interaction rule for vote casting. Example: vote_type='up'.
  vote_type String

  /// Timestamp when the vote was created/cast. Required for audit and analytics (e.g., changing votes over time).
  created_at DateTime @db.Timestamptz

  /// Timestamp for vote changes (e.g., toggling from up to down, or undoing vote). Null if never changed.
  updated_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_discussionboard_comment_votes_comment discussionboard_comments @relation(fields: [discussionboard_comment_id], references: [id], onDelete: Cascade)
  fk_discussionboard_comment_votes_member  discussionboard_members  @relation(fields: [discussionboard_member_id], references: [id], onDelete: Cascade)

  @@unique([discussionboard_comment_id, discussionboard_member_id])
  @@index([discussionboard_member_id])
  @@index([created_at])
}

/// Normalized reporting record for moderation/audit—implements requirements for Member moderation participation, Moderation & Reporting workflows, and audit escalation (see requirements: 4, 8). Each record represents one member's report against one comment for a specific reason, referencing report types (already implemented) and moderation flow. Maintains full normalization. Example: When a member reports a comment, a new record is created (with a type, reference to reporting member and targeted comment). Special behaviors: Uniqueness constraint prevents redundant reports by the same member for the same comment and type.
///
/// @namespace Comments
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_comment_reports {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies each comment report entry.
  id String @id @db.Uuid

  /// Target comment's {@link discussionboard_comments.id}—the comment being reported for review.
  discussionboard_comment_id String @db.Uuid

  /// Reporting member's {@link discussionboard_members.id}—who filed the report.
  discussionboard_member_id String @db.Uuid

  /// Type/category of the report, from {@link discussionboard_report_types.id}—e.g., spam, abuse, off-topic (for analytics and escalation flow).
  discussionboard_report_type_id String @db.Uuid

  /// Detailed user-supplied explanation of why the comment is being reported—implements requirements for nuanced moderation case handling and transparency. E.g., "This comment contains hate speech." Null not allowed for accountability.
  reason String

  /// Timestamp when the report was made. Required for audit trail, moderator SLAs, and activity analysis.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_discussionboard_comment_reports_comment     discussionboard_comments     @relation(fields: [discussionboard_comment_id], references: [id], onDelete: Cascade)
  fk_discussionboard_comment_reports_member      discussionboard_members      @relation(fields: [discussionboard_member_id], references: [id], onDelete: Cascade)
  fk_discussionboard_comment_reports_report_type discussionboard_report_types @relation(fields: [discussionboard_report_type_id], references: [id], onDelete: Cascade)

  @@unique([discussionboard_comment_id, discussionboard_member_id, discussionboard_report_type_id])
  @@index([discussionboard_member_id])
  @@index([discussionboard_report_type_id])
  @@index([created_at])
  @@index([reason(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.schema-07-moderation.prisma:
/// Discussion Board Report Record - Implements the reporting and escalation flow described in the requirements (see 'Business Rules & Workflows,' 'Moderation & Escalation Workflows').
///
/// Business Purpose: Captures member-initiated reports on inappropriate content or suspicious users, forming the starting point for moderation review. Maintains 3NF compliance by separating report metadata from other business entities. For example, a member reporting a post or comment for spam or abuse will be registered as a discussionboard_reports entry referencing the reported item and the reporting member.
///
/// Key relationships: Connects to report type, target object (via foreign key to posts, comments, or users), and the reporting actor (from already created discussionboard_members table).
/// Special behaviors: Supports audit trail, links to downstream moderation actions, and enforces one report per object/member per unique incident.
///
/// @namespace Moderation
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_reports {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for the report record.
  id String @id @db.Uuid

  /// Associated report type {@link discussionboard_report_types.id} identifying the reason for report (e.g., spam, abuse, misinformation).
  discussionboard_report_type_id String @db.Uuid

  /// The reporting member's {@link discussionboard_members.id} who filed the report.
  reporting_member_id String @db.Uuid

  /// Target business object being reported (post, comment, or user, as per assignment). The true type is determined by context on review. Implements the polymorphic target pattern in a fully normalized way (all references are UUIDs only).
  target_object_id String @db.Uuid

  /// Type of object being reported. Implements requirement to generalize reporting (e.g., 'post', 'comment', 'member'). Used by moderation workflows to route and describe moderation procedures.
  target_object_type String

  /// Reporter supporting detail or description. Implements requirement for explanation or supporting evidence. Maintains normalization: only the specific explanation for this incident.
  report_description String?

  /// Timestamp of report creation. Implements audit trail and supports compliance/SLA tracking as required by moderation workflow.
  reported_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_discussionboard_reports_report_type      discussionboard_report_types @relation(fields: [discussionboard_report_type_id], references: [id], onDelete: Cascade)
  fk_discussionboard_reports_reporting_member discussionboard_members      @relation(fields: [reporting_member_id], references: [id], onDelete: Cascade)

  discussionboard_moderation_actions discussionboard_moderation_actions[]
  discussionboard_bans               discussionboard_bans[]
  discussionboard_warnings           discussionboard_warnings[]

  @@unique([target_object_id, target_object_type, reporting_member_id])
  @@index([discussionboard_report_type_id])
  @@index([reporting_member_id])
  @@index([reported_at])
}

/// Report Type Registry - Implements the classification of reportable incident subjects (see Business Requirements, Content Quality Assurance, and Moderation documentation).
///
/// Business Purpose: Provides an extensible classification system for report reasons (e.g., spam, abuse, misinformation) as required for moderation triage. Maintains 3NF compliance by separating report type code/label definitions from actual reports.
///
/// Key relationships: Referenced by discussionboard_reports entries.
/// Special behaviors: Codes must be unique. Used by the frontend to present selectable reasons for reporting content.
///
/// @namespace Moderation
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_report_types {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Short, unique report type code (e.g., 'spam', 'abuse'). Used for frontend and backend logic to reference the report type.
  code String

  /// User-visible name of the report type for UI display.
  display_name String

  /// Long-form description for mods/admins. Clarifies what constitutes this report type. Aids in moderation process training.
  description String?

  /// Whether this report type is currently selectable (e.g., deprecated types are marked inactive, for regulatory or policy changes).
  active Boolean

  /// Timestamp when this type was created (registry audit trail, required for governance and compliance tracking).
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  discussionboard_post_reports    discussionboard_post_reports[]
  discussionboard_comment_reports discussionboard_comment_reports[]
  discussionboard_reports         discussionboard_reports[]

  @@unique([code])
  @@index([active])
  @@index([display_name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Moderation Action Record - Implements the 'Action Workflow' and audit requirements specified for both moderators and admins (see Workflows section, Requirement 3: "Moderation & Reporting").
///
/// Business Purpose: Tracks every moderation intervention taken in response to reports: edits, deletions, warnings, bans, pin/unpin, locks.
///
/// Maintains normalization by linking to the originating report (if any), the acting moderator/admin, and the target object. No pre-calculated summaries or denormalization.
///
/// Key relationships: Connects to discussionboard_reports; references acting moderator/admin (otherComponents); links to object of action (via polymorphic pattern).
/// Special behaviors: Each action includes rationale, timestamps, and type.
///
/// @namespace Moderation
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_moderation_actions {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each moderation action.
  id String @id @db.Uuid

  /// Associated report {@link discussionboard_reports.id} if this action originates from a user report (nullable for proactive/patrol actions).
  report_id String? @db.Uuid

  /// Acting moderator or admin {@link discussionboard_moderators.id or discussionboard_admins.id} who performed the action.
  acting_moderator_id String @db.Uuid

  /// Target business object being moderated (post, comment, member, etc.). Same pattern as reports for generalized reference.
  target_object_id String @db.Uuid

  /// Type of object being moderated ('post', 'comment', 'member', 'board', etc.). Maintains the normalized reference per domain context.
  target_object_type String

  /// Type of moderation action taken (e.g., 'warn', 'edit', 'delete', 'ban', 'lock', 'pin', etc.). Enables analytics integration for action type filtering.
  action_type String

  /// Explanation and notes justifying the action. Fulfills requirement for rationale documentation and behavioral transparency. Maintains 3NF (no cross-table references stored here).
  rationale String

  /// Timestamp when the action was performed. Used for audit log, SLA tracking, and analytics.
  actioned_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_moderation_actions_report    discussionboard_reports?   @relation(fields: [report_id], references: [id], onDelete: Cascade)
  fk_moderation_actions_moderator discussionboard_moderators @relation(fields: [acting_moderator_id], references: [id], onDelete: Cascade)

  @@index([report_id])
  @@index([acting_moderator_id])
  @@index([actioned_at])
  @@index([rationale(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Ban/Suspension Record - Implements member bans and suspensions per Moderation business rules and workflows (see escalation section, warnings > temp ban > perm ban).
///
/// Business Purpose: Captures formal restrictions on members' system access/abilities after infractions are verified. Retains 3NF by referencing the subject (member id), the moderator/admin, and the originating report or rationale (if present).
///
/// Key relationships: Links to ban subject (member), acting moderator/admin, and referenced report.
/// Special behaviors: Multiple bans per member possible if for separate incidents. Each ban is atomic and historical for audit/compliance. Dates track duration and compliance requirements.
///
/// @namespace Moderation
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_bans {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// The banned member's {@link discussionboard_members.id} subject to ban action.
  banned_member_id String @db.Uuid

  /// Moderator/admin {@link discussionboard_moderators.id or discussionboard_admins.id} who enacted the ban (compliance/audit).
  acting_moderator_id String @db.Uuid

  /// Originating {@link discussionboard_reports.id} if the ban was triggered by a specific report (nullable for proactive major bans).
  report_id String? @db.Uuid

  /// Ban reason (human-meaningful summary for compliance/audit, visible in appeals workflows).
  reason String

  /// Type: 'temporary' or 'permanent' as per business rules (see moderation escalation workflows).
  ban_type String

  /// Start datetime of the ban (when enforced).
  banned_at DateTime @db.Timestamptz

  /// When ban ends (nullable for permanent bans). Maintains normalized structure for expiry logic.
  expires_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_bans_banned_member    discussionboard_members    @relation(fields: [banned_member_id], references: [id], onDelete: Cascade)
  fk_bans_acting_moderator discussionboard_moderators @relation(fields: [acting_moderator_id], references: [id], onDelete: Cascade)
  fk_bans_report           discussionboard_reports?   @relation(fields: [report_id], references: [id], onDelete: Cascade)

  @@index([acting_moderator_id])
  @@index([report_id])
  @@index([banned_member_id])
  @@index([banned_at])
}

/// Warning Issuance Record - Implements the warning step in the moderation escalation pipeline (see Business Rules, "Members receive warnings for policy violations; repeated offenses escalate").
///
/// Business Purpose: Records the issuance of official warnings to members, described as the first step in the escalating penalty process. 3NF compliance is maintained by linking each warning to the subject member and the moderator/admin, as well as any originating report. Warnings are atomic events, not aggregated (no counts or derived statuses are stored here).
///
/// Key relationships: Related to members (warned_member_id), linked to moderator/admin, and can reference a report.
/// Special behaviors: Multiple warnings per member are possible; each is an independent event for audit trail and escalation automation.
///
/// @namespace Moderation
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_warnings {
  //----
  // COLUMNS
  //----
  /// Primary Key for each warning record.
  id String @id @db.Uuid

  /// Member who receives the warning {@link discussionboard_members.id}.
  warned_member_id String @db.Uuid

  /// Moderator/admin issuing the warning {@link discussionboard_moderators.id or discussionboard_admins.id}.
  acting_moderator_id String @db.Uuid

  /// Report that caused the warning (nullable if warning is preemptive or for off-platform evidence).
  report_id String? @db.Uuid

  /// Warning reason, descriptive text stating the violation or risk observed. Implements need for clarity and behavioral documentation.
  reason String

  /// Timestamp when warning was applied. Maintains full audit traceability.
  warned_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_warnings_warned_member    discussionboard_members    @relation(fields: [warned_member_id], references: [id], onDelete: Cascade)
  fk_warnings_acting_moderator discussionboard_moderators @relation(fields: [acting_moderator_id], references: [id], onDelete: Cascade)
  fk_warnings_report           discussionboard_reports?   @relation(fields: [report_id], references: [id], onDelete: Cascade)

  @@index([acting_moderator_id])
  @@index([report_id])
  @@index([warned_member_id])
  @@index([warned_at])
}

schemas.schema-08-analytics.prisma:
/// Tracks post, comment, and voting engagement across users, threads, boards, and time windows. Implements business requirements from analytics use cases (see doc 01 and 02), providing the basis for DAU/WAU charts, cohort analysis, board-level tracking, and moderation metrics. Maintains 3NF by atomically tracking metrics by entity and period, with all pre-calculated/aggregated fields in materialized views only. For example, storing counts of posts, comments, reactions (upvotes/downvotes) per entity per period (e.g., daily). Referenced by analytics dashboards; connects to members, boards, and time periods for detailed engagement breakdowns. Special behaviors: Ensures only raw, non-pre-aggregated, normalized metrics for further processing; NO denormalized fields here.
///
/// @namespace Analytics
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_engagement_metrics {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each engagement metric record.
  id String @id @db.Uuid

  /// The member whose engagement is being recorded. Points to {@link discussionboard_members.id} in Actors domain. Supports analytics per user metric.
  discussionboard_member_id String? @db.Uuid

  /// The board where engagement occurs. Points to {@link discussionboard_boards.id} in Boards domain. Enables board-level metric analysis.
  discussionboard_board_id String? @db.Uuid

  /// Date for the measured engagement activity. Used for time-bucketed DAU/WAU analysis. Normalization: atomic date, not derived.
  engagement_date DateTime @db.Timestamptz

  /// Number of posts created by the referenced member on the board for the day. Implements requirement for tracking post volume. Not pre-aggregated; count is atomic per user/board/date.
  posts_created_count Int @db.Integer

  /// Number of comments created. Supports moderation and content quality metrics.
  comments_created_count Int @db.Integer

  /// Number of voting actions (upvotes/downvotes) performed by the user on the board in the period. Fulfills analysis requirement for voting engagement.
  votes_cast_count Int @db.Integer

  //----
  // RELATIONS
  //----
  fk_engagemetric_member discussionboard_members? @relation(fields: [discussionboard_member_id], references: [id], onDelete: Cascade)
  fk_engagemetric_board  discussionboard_boards?  @relation(fields: [discussionboard_board_id], references: [id], onDelete: Cascade)

  @@unique([discussionboard_member_id, discussionboard_board_id, engagement_date])
  @@index([engagement_date])
  @@index([discussionboard_member_id, engagement_date])
  @@index([discussionboard_board_id, engagement_date])
}

/// Stores a normalized, queryable log of analytic events related to member activity across the platform, as required by doc 02 User Journeys and Analytics Use Cases. Implements raw event stream/log for tracking time series activity (e.g., logins, post creations, comment edits, account changes, board visits) for audit and analytics. Maintains 3NF: each row records precisely one event; all aggregation occurs in materialized views. Connected to member, optional thread, board, post, or comment. Used for audit, anomaly detection, rare journey tracking, and engagement heatmaps (e.g., heatmap visualizations of peak platform activity). Special: Enforces normalized, atomic event records (not summary counts).
///
/// @namespace Analytics
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_activity_logs {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each activity log record.
  id String @id @db.Uuid

  /// Member acting in the event (nullable for system/non-member events). References {@link discussionboard_members.id}.
  discussionboard_member_id String? @db.Uuid

  /// Board related to the activity (nullable when not board-specific). References {@link discussionboard_boards.id}.
  discussionboard_board_id String? @db.Uuid

  /// Thread related to the event. Nullable if event is not thread-specific. References {@link discussionboard_threads.id}.
  discussionboard_thread_id String? @db.Uuid

  /// Post involved in the event. Nullable unless directly post-related. References {@link discussionboard_posts.id}.
  discussionboard_post_id String? @db.Uuid

  /// Comment involved in the event. Nullable unless directly comment-related. References {@link discussionboard_comments.id}.
  discussionboard_comment_id String? @db.Uuid

  /// Timestamp of the event/action for precise time series and audit. Implements analytics requirements for time-based user activity tracking.
  event_timestamp DateTime @db.Timestamptz

  /// Type of activity (e.g., 'login', 'logout', 'post_create', 'post_edit', 'post_delete', 'comment_create', 'comment_edit', 'comment_delete', 'vote', 'visit_board', 'ban', 'role_change', 'notification_viewed', etc.) Implements analytics, moderation, and auditing requirements.
  event_type String

  /// Free-form JSON, stringified, with additional event context (device, IP, old/new values, change details, etc.). Implements rare journeys analysis and audit trails.
  event_metadata String?

  //----
  // RELATIONS
  //----
  fk_activitylog_member  discussionboard_members?  @relation(fields: [discussionboard_member_id], references: [id], onDelete: Cascade)
  fk_activitylog_board   discussionboard_boards?   @relation(fields: [discussionboard_board_id], references: [id], onDelete: Cascade)
  fk_activitylog_thread  discussionboard_threads?  @relation(fields: [discussionboard_thread_id], references: [id], onDelete: Cascade)
  fk_activitylog_post    discussionboard_posts?    @relation(fields: [discussionboard_post_id], references: [id], onDelete: Cascade)
  fk_activitylog_comment discussionboard_comments? @relation(fields: [discussionboard_comment_id], references: [id], onDelete: Cascade)

  @@index([discussionboard_thread_id])
  @@index([discussionboard_post_id])
  @@index([discussionboard_comment_id])
  @@index([discussionboard_member_id, event_timestamp])
  @@index([event_type, event_timestamp])
  @@index([discussionboard_board_id, event_timestamp])
}

/// Tracks active/trending topics (thread/post/title combos) for the trending panel and analytics dashboards. Implements analytics requirements for highlighting trending discussions, detecting viral posts, and displaying platform trends by period. Maintains 3NF: one row per topic per period, with rankings and trend markers computed externally or in mv_ tables (no denormalized fields here). Example: records trending score of a thread in a given day, referenced for homepage highlights. Connected to threads, board; enables detection of surging topics to alert moderation or trigger notifications. Special behaviors: Atomic data only, NO pre-aggregated lists or computed fields.
///
/// @namespace Analytics
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_trending_topics {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each trending topic record.
  id String @id @db.Uuid

  /// Thread considered as trending. References {@link discussionboard_threads.id}.
  discussionboard_thread_id String @db.Uuid

  /// Board under which the trending thread is tracked. References {@link discussionboard_boards.id}.
  discussionboard_board_id String @db.Uuid

  /// Date for which the trending status/ranking is recorded. Implements period-based (e.g., daily) tracking of trending status per topic.
  ranking_period_date DateTime @db.Timestamptz

  /// Quantitative score for the topic's trending calculation—not precomputed, but source score as calculated by external analytics engine or background job. Implements requirement for ordering trending panels. (e.g., engagement-weighted activity score)
  trending_score Float @db.DoublePrecision

  //----
  // RELATIONS
  //----
  fk_trending_topic_thread discussionboard_threads @relation(fields: [discussionboard_thread_id], references: [id], onDelete: Cascade)
  fk_trending_topic_board  discussionboard_boards  @relation(fields: [discussionboard_board_id], references: [id], onDelete: Cascade)

  @@unique([discussionboard_thread_id, ranking_period_date])
  @@index([ranking_period_date])
  @@index([discussionboard_board_id, ranking_period_date])
}

schemas.schema-09-notifications.prisma:
/// Notification Template Entity - This implements the requirement for system-triggered notifications from the requirements document (Business Requirements: 6. Notifications & Updates, 9. Data Privacy & Protection). 
///
/// Business explanation: Enables the platform to manage, organize, and version all message templates used for member notifications (email, in-app, browser). Maintains 3NF normalization by splitting templates from notification triggers and user preferences, thus providing single-source for reusable content. For example, a template defines the body for 'Thread Reply', which can then be used by various notification jobs/services. 
///
/// Key relationships: No direct foreign keys. Templates are referenced by notification delivery engines and preference settings elsewhere in the system. 
/// Special behaviors: Supports audit trails, mutable content with unique code per template, version history if needed.
///
/// @namespace Notifications
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_notification_templates {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies each notification template.
  id String @id @db.Uuid

  /// Template Code - Implements template identification and enforcement. Business meaning: Unique short string used to reference this template (e.g., 'reply_notification'). Separates template logic from notification event logic, enables auditability by code, and prevents duplicates. Example: Used by notification jobs to fetch rendered content for email or in-app use. Constraint: Must be unique across all templates.
  code String

  /// Template Name - Implements template user-friendly reference. Business meaning: Human-readable title for each notification template. Ensures normalization by preventing use of business data in multiple places. Example: Shown to admins when configuring notification settings. Constraint: Must not be null.
  name String

  /// Template Description - Provides extended context for admins. Business meaning: A sentence or two that describes the intent or use-case of the template. Ensures normalization by allowing proper documentation in one place. Example: 'Sent when a user receives a reply to their thread.' Nullable for brevity in simple templates.
  description String?

  /// Template Subject - Implements message subject customization. Business meaning: Used for email or notification headers. Ensures clear communication and organization. Example: '[DiscussionBoard] New reply to your thread'. Constraint: Not nullable for communication clarity.
  subject String

  /// Template Body - The main message content, possibly with placeholders. Ensures normalization by centralizing source message text for all notification jobs/services. Example: 'Hello {{username}}, your post received a reply...'. May use parameter placeholders for personalization. Not nullable to ensure every template is usable.
  body String

  /// Active Status Flag - Indicates if this template is available for use. Implements enable/disable without deletion for audit trails and error prevention. Example: Deactivating a deprecated or seasonal template. Not nullable.
  is_active Boolean

  /// Creation Timestamp - Implements audit trail requirement (Business Rules: Section 6). Business meaning: When was the template created. 3NF compliance by storing as atomic value. Not nullable.
  created_at DateTime @db.Timestamptz

  /// Update Timestamp - Implements last-modified tracking. Records when the template was last edited. Normalized per audit/compliance guidance. Not nullable.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([code])
  @@index([is_active])
  @@index([created_at])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([subject(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Notification Preferences Entity - Implements user-specific notification customization per Business Requirement 6 (Notifications & Updates) and 3 (User Journey & Use Cases). 
///
/// Business explanation: Stores each member’s notification channel preferences for different template types (e.g., email, SMS, in-app). Supports compliance with data privacy laws by honoring user opt-in/out settings. Enforces normalization by decoupling per-user/channel rules from system triggers and message templates. Example: User sets 'email' notifications only for mentions, but not for thread replies. 
///
/// Key relationships: Links to discussionboard_members via foreign key. References notification template codes for channel granularity. 
/// Special behaviors: Each (member_id, code) pair must be unique. Allows for per-template and per-channel enable/disable granularity. Audit fields included for compliance.
///
/// @namespace Notifications
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_notification_preferences {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies each notification preference row.
  id String @id @db.Uuid

  /// Belonged member’s {@link discussionboard_members.id}. Links notification preference to user account.
  discussionboard_member_id String @db.Uuid

  /// Notification Template Code - Implements per-template preference setting. Business meaning: Which notification type this preference applies to. Ensures normalization by not embedding template details; only links by code. Not nullable.
  code String

  /// Enable for Email - Indicates if the member wants email notifications for this code. Implements granular opt-in control (required for privacy regulations). Not nullable.
  email_enabled Boolean

  /// Enable for In-App - Indicates if in-app/bell notifications are enabled. Business meaning: Supports per-channel enable/disable. Not nullable.
  inapp_enabled Boolean

  /// Enable for Browser Push - Channel preference for browser push notifications. Ensures each user can control channel specificity. Not nullable.
  browser_enabled Boolean

  /// Creation Timestamp - For audit and compliance tracking. Not nullable.
  created_at DateTime @db.Timestamptz

  /// Update Timestamp - Last modified tracking. Ensures temporal auditability. Not nullable.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_discussionboard_notification_preferences_member discussionboard_members @relation(fields: [discussionboard_member_id], references: [id], onDelete: Cascade)

  @@unique([discussionboard_member_id, code])
  @@index([discussionboard_member_id])
  @@index([code])
  @@index([email_enabled])
}

schemas.schema-10-privacy.prisma:
/// Privacy Policy – This model implements the explicit business requirement for transparent privacy and data protection policies outlined in the platform requirements. Each record stores a distinct, time-versioned policy for audit, legal compliance, and user access. Policies are never overwritten, ensuring a full historical audit trail and 3NF normalization. Example: When a new version of the privacy policy is adopted, a new record is inserted; users can access the version effective when they joined.
///
/// @namespace Privacy
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_privacy_policies {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique policy version identifier. Ensures entity singularity for audit/history.
  id String @id @db.Uuid

  /// Policy Version – Structured textual identifier (e.g., 'v2024.06') referenced in logs or member consent records. Uniquely identifies each record. Normalized, atomic.
  version String

